import gzip
import pathlib

import pytest

import gzip_bench

MB = 1024 * 1024


@pytest.fixture(scope="session")
def results(tmp_path_factory):
    """Run the full benchmark pipeline once and share results across tests."""
    workdir = tmp_path_factory.mktemp("gzip_bench")
    return gzip_bench.run_benchmark(workdir)


def test_source_generated_at_expected_size(results):
    assert results["source_size"] == 40 * MB


def test_whole_blob_decompressed_hash_matches_source(results):
    assert results["whole"].decompressed_sha256 == results["source_sha256"]


def test_streaming_decompressed_hash_matches_source(results):
    assert results["streaming"].decompressed_sha256 == results["source_sha256"]


def test_streaming_peak_under_3mb(results):
    assert results["streaming"].peak_bytes < 3 * MB, (
        f"streaming peak was {results['streaming'].peak_bytes / MB:.2f} MiB"
    )


def test_whole_blob_peak_exceeds_40mb(results):
    assert results["whole"].peak_bytes > 40 * MB, (
        f"whole-blob peak was {results['whole'].peak_bytes / MB:.2f} MiB"
    )


def test_both_outputs_are_valid_gzip_files(results):
    assert isinstance(
        gzip.decompress(results["whole"].output_path.read_bytes()), bytes
    ), "whole_blob.gz did not decompress via gzip.decompress"
    assert gzip_bench.is_valid_gzip(results["whole"].output_path)
    assert gzip_bench.is_valid_gzip(results["streaming"].output_path)


def test_decompressed_contents_identical(results):
    whole_plain = gzip.decompress(results["whole"].output_path.read_bytes())
    stream_plain = gzip.decompress(results["streaming"].output_path.read_bytes())
    assert hashlib_like(whole_plain) == hashlib_like(stream_plain)
    assert whole_plain == stream_plain


def test_report_written_with_required_sections(results):
    report_path = pathlib.Path(results["source_path"]).parent / "gzip_report.md"
    assert report_path.exists(), "gzip_report.md was not produced"
    text = report_path.read_text()
    for needle in (
        "tracemalloc peak",
        "SHA-256",
        "differ byte-for-byte",
        "MTIME",
    ):
        assert needle in text, f"report missing section/keyword: {needle!r}"


def hashlib_like(data: bytes) -> str:
    import hashlib

    return hashlib.sha256(data).hexdigest()
